-- Ahde Vefa full platform extension. Apply manually after 20261122000000_initial_schema.sql.
begin;
create schema if not exists private;
alter table public.profiles add column if not exists suspended boolean not null default false;
alter table public.posts alter column author_id drop not null;
alter table public.posts add column if not exists title text not null default '';
alter table public.posts add column if not exists type text not null default 'text';
alter table public.posts add column if not exists area text not null default 'dergah';
alter table public.posts add column if not exists anonymous boolean not null default false;
alter table public.posts add column if not exists teacher_id uuid references public.teachers(id);
alter table public.posts add column if not exists group_id uuid;
alter table public.lessons add column if not exists kind text not null default 'lesson';
alter table public.lessons add column if not exists work_title text not null default '';
alter table public.lessons add column if not exists license text not null default '';
alter table public.lessons add column if not exists permission_confirmed boolean not null default false;
alter table public.letters add column if not exists subject text not null default '';
alter table public.letters add column if not exists deliver_at timestamptz;
alter table public.letters add column if not exists delivered_at timestamptz;
alter table public.letters add column if not exists status text not null default 'draft' check(status in ('draft','sent'));
alter table public.library_items add column if not exists owner_id uuid references public.profiles(id) on delete cascade;
create table if not exists public.teacher_requests(id uuid primary key default gen_random_uuid(), user_id uuid not null unique references public.profiles(id) on delete cascade, bio text not null default '' check(char_length(bio)<=2000), status text not null default 'pending' check(status in ('pending','approved','rejected')), created_at timestamptz not null default now(), decided_at timestamptz);
create table if not exists public.teacher_notes(id uuid primary key default gen_random_uuid(), teacher_id uuid not null references public.profiles(id) on delete cascade, student_id uuid not null references public.profiles(id) on delete cascade, title text not null default '' check(char_length(title)<=200), body text not null default '' check(char_length(body)<=10000), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.platform_settings(key text primary key, value jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(), actor_id uuid not null references public.profiles(id), action text not null, target_id uuid, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.media_files(id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id) on delete cascade, path text not null unique, mime_type text not null, size_bytes integer not null check(size_bytes between 1 and 20971520), created_at timestamptz not null default now());
create table if not exists public.post_saves(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, post_id uuid not null references public.posts(id) on delete cascade, unique(user_id,post_id));
create table if not exists public.user_blocks(blocker_id uuid not null references public.profiles(id) on delete cascade, blocked_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(blocker_id,blocked_id), check(blocker_id<>blocked_id));
create table if not exists public.event_registrations(event_id uuid not null references public.events(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(event_id,user_id));
create table if not exists public.letter_archives(letter_id uuid not null references public.letters(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, archived_at timestamptz not null default now(), primary key(letter_id,user_id));
create table if not exists private.post_owners(post_id uuid primary key references public.posts(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade);
create index if not exists posts_area_feed_idx on public.posts(area,visibility,status,created_at desc);
create index if not exists media_owner_idx on public.media_files(owner_id,created_at desc);
create index if not exists letters_delivery_idx on public.letters(recipient_id,deliver_at,status);
insert into storage.buckets(id,name,public) values('platform-media','platform-media',false) on conflict(id) do nothing;
create or replace function public.public_profiles(_ids uuid[]) returns table(id uuid,full_name text,username text,bio text) language sql stable security definer set search_path=public,pg_catalog as $$ select p.id,p.full_name,p.username,p.bio from public.profiles p where p.id=any(coalesce(_ids,'{}'::uuid[])) limit 100 $$;
create or replace function public.search_members(_query text) returns table(id uuid,full_name text,username text,bio text) language sql stable security definer set search_path=public,pg_catalog as $$ select p.id,p.full_name,p.username,p.bio from public.profiles p where auth.uid() is not null and char_length(trim(_query))>=2 and (p.username ilike '%'||trim(_query)||'%' or p.full_name ilike '%'||trim(_query)||'%') and p.suspended=false and p.id<>auth.uid() limit 20 $$;
create or replace function public.owned_post_ids() returns setof uuid language sql stable security definer set search_path=public,private,pg_catalog as $$ select post_id from private.post_owners where user_id=auth.uid() $$;
create or replace function private.owns_post(_post_id uuid,_user_id uuid) returns boolean language sql stable security definer set search_path=public,private,pg_catalog as $$ select exists(select 1 from private.post_owners where post_id=_post_id and user_id=_user_id) $$;
create or replace function public.create_post(_data jsonb) returns jsonb language plpgsql security definer set search_path=public,private,pg_catalog as $$ declare x public.posts; anon boolean; begin if auth.uid() is null then raise exception 'auth required'; end if; anon=coalesce((_data->>'anonymous')::boolean,false); insert into public.posts(author_id,title,body,type,area,visibility,status,anonymous,teacher_id) values(case when anon then null else auth.uid() end,coalesce(_data->>'title',''),coalesce(_data->>'body',''),coalesce(_data->>'type','text'),coalesce(_data->>'area','dergah'),coalesce(_data->>'visibility','public'),'published',anon,nullif(_data->>'teacher_id','')::uuid) returning * into x; insert into private.post_owners(post_id,user_id) values(x.id,auth.uid()); return to_jsonb(x); end $$;
create or replace function public.apply_teacher(_teacher_id uuid,_message text) returns jsonb language plpgsql security definer set search_path=public,pg_catalog as $$ declare x public.teacher_applications; begin if auth.uid() is null or exists(select 1 from public.profiles where id=auth.uid() and suspended) then raise exception 'not allowed'; end if; insert into public.teacher_applications(student_id,teacher_id,message) values(auth.uid(),_teacher_id,coalesce(_message,'')) returning * into x; return to_jsonb(x); end $$;
create or replace function public.decide_teacher_application(_application_id uuid,_approve boolean) returns jsonb language plpgsql security definer set search_path=public,pg_catalog as $$ declare a public.teacher_applications; begin select * into a from public.teacher_applications where id=_application_id for update; if a.id is null or a.teacher_id<>auth.uid() or not exists(select 1 from public.teachers where id=auth.uid() and approved) then raise exception 'not allowed'; end if; if a.status<>'pending' then raise exception 'already decided'; end if; update public.teacher_applications set status=case when _approve then 'approved' else 'rejected' end,decided_at=now() where id=a.id; if _approve then insert into public.teacher_students(teacher_id,student_id) values(auth.uid(),a.student_id) on conflict(teacher_id,student_id) do update set active=true,ended_at=null; update public.roles set role='dervish',updated_at=now() where user_id=a.student_id and role='member'; end if; return jsonb_build_object('id',a.id,'approved',_approve); end $$;
create or replace function public.apply_as_teacher(_bio text) returns jsonb language plpgsql security definer set search_path=public,pg_catalog as $$ declare x public.teacher_requests; begin if auth.uid() is null then raise exception 'auth required'; end if; insert into public.teacher_requests(user_id,bio) values(auth.uid(),left(coalesce(_bio,''),2000)) on conflict(user_id) do update set bio=excluded.bio,status='pending',decided_at=null returning * into x; return to_jsonb(x); end $$;
create or replace function public.approve_teacher(_request_id uuid,_approve boolean) returns jsonb language plpgsql security definer set search_path=public,pg_catalog as $$ declare x public.teacher_requests; begin if not exists(select 1 from public.roles where user_id=auth.uid() and role='admin') then raise exception 'not allowed'; end if; select * into x from public.teacher_requests where id=_request_id for update; if x.id is null then raise exception 'not found'; end if; update public.teacher_requests set status=case when _approve then 'approved' else 'rejected' end,decided_at=now() where id=x.id; if _approve then insert into public.teachers(id,display_name,bio,approved) select x.user_id,p.full_name,x.bio,true from public.profiles p where p.id=x.user_id on conflict(id) do update set approved=true,bio=excluded.bio; update public.roles set role='teacher',updated_at=now() where user_id=x.user_id; end if; return jsonb_build_object('id',x.id,'approved',_approve); end $$;
create or replace function public.admin_set_role(_user_id uuid,_role text) returns jsonb language plpgsql security definer set search_path=public,pg_catalog as $$ begin if not exists(select 1 from public.roles where user_id=auth.uid() and role='admin') or _role not in ('member','dervish','teacher','admin') then raise exception 'not allowed'; end if; update public.roles set role=_role,updated_at=now() where user_id=_user_id; return jsonb_build_object('user_id',_user_id,'role',_role); end $$;
create or replace function public.admin_set_suspension(_user_id uuid,_suspended boolean) returns jsonb language plpgsql security definer set search_path=public,pg_catalog as $$ begin if not exists(select 1 from public.roles where user_id=auth.uid() and role='admin') or _user_id=auth.uid() then raise exception 'not allowed'; end if; update public.profiles set suspended=_suspended,updated_at=now() where id=_user_id; return jsonb_build_object('user_id',_user_id,'suspended',_suspended); end $$;
create or replace function public.admin_statistics() returns jsonb language sql security definer set search_path=public,pg_catalog as $$ select jsonb_build_object('users',(select count(*) from public.profiles),'teachers',(select count(*) from public.teachers where approved),'posts',(select count(*) from public.posts where status='published'),'reports',(select count(*) from public.reports),'lessons',(select count(*) from public.lessons where is_published),'library_items',(select count(*) from public.library_items where is_published)) where exists(select 1 from public.roles where user_id=auth.uid() and role='admin') $$;
create or replace function public.admin_users(_query text default '') returns table(id uuid,full_name text,username text,email text,role text,suspended boolean,created_at timestamptz) language sql security definer set search_path=public,pg_catalog as $$ select p.id,p.full_name,p.username,u.email,r.role,p.suspended,p.created_at from public.profiles p join auth.users u on u.id=p.id join public.roles r on r.user_id=p.id where exists(select 1 from public.roles me where me.user_id=auth.uid() and me.role='admin') and (coalesce(_query,'')='' or p.username ilike '%'||_query||'%' or p.full_name ilike '%'||_query||'%') limit 100 $$;
create or replace function public.process_my_due_items() returns integer language plpgsql security definer set search_path=public,pg_catalog as $$ declare n integer; begin update public.letters set delivered_at=now() where recipient_id=auth.uid() and status='sent' and deliver_at is not null and deliver_at<=now() and delivered_at is null; get diagnostics n=row_count; return n; end $$;
create or replace function private.can_read_media(_path text) returns boolean language sql stable security definer set search_path=public,private,pg_catalog as $$ select exists(select 1 from public.media_files m where m.path=_path and (m.owner_id=auth.uid() or exists(select 1 from public.posts p where _path=any(p.media_paths) and p.visibility='public' and p.status='published'))) $$;
revoke all on function public.create_post(jsonb) from public; grant execute on function public.create_post(jsonb) to authenticated;
revoke all on function public.apply_teacher(uuid,text) from public; grant execute on function public.apply_teacher(uuid,text) to authenticated;
revoke all on function public.decide_teacher_application(uuid,boolean) from public; grant execute on function public.decide_teacher_application(uuid,boolean) to authenticated;
revoke all on function public.apply_as_teacher(text) from public; grant execute on function public.apply_as_teacher(text) to authenticated;
revoke all on function public.approve_teacher(uuid,boolean) from public; grant execute on function public.approve_teacher(uuid,boolean) to authenticated;
revoke all on function public.admin_set_role(uuid,text) from public; grant execute on function public.admin_set_role(uuid,text) to authenticated;
revoke all on function public.admin_set_suspension(uuid,boolean) from public; grant execute on function public.admin_set_suspension(uuid,boolean) to authenticated;
revoke all on function public.admin_statistics() from public; grant execute on function public.admin_statistics() to authenticated;
revoke all on function public.admin_users(text) from public; grant execute on function public.admin_users(text) to authenticated;
revoke all on function public.public_profiles(uuid[]) from public; grant execute on function public.public_profiles(uuid[]) to authenticated,anon;
revoke all on function public.search_members(text) from public; grant execute on function public.search_members(text) to authenticated;
revoke all on function public.process_my_due_items() from public; grant execute on function public.process_my_due_items() to authenticated;
revoke all on function private.owns_post(uuid,uuid) from public,anon; grant execute on function private.owns_post(uuid,uuid) to authenticated;

do $$ declare t text; begin foreach t in array array['teacher_requests','teacher_notes','platform_settings','audit_logs','media_files','post_saves','user_blocks','event_registrations','letter_archives'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy teacher_requests_owner on public.teacher_requests for select using(user_id=auth.uid() or exists(select 1 from public.roles where user_id=auth.uid() and role='admin'));
create policy teacher_notes_participant on public.teacher_notes for all using(teacher_id=auth.uid() or student_id=auth.uid());
create policy media_owner on public.media_files for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy saves_owner on public.post_saves for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy blocks_owner on public.user_blocks for all using(blocker_id=auth.uid()) with check(blocker_id=auth.uid());
create policy event_reg_owner on public.event_registrations for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy letter_archive_owner on public.letter_archives for all using(user_id=auth.uid()) with check(user_id=auth.uid());

-- The foundation migration deliberately revoked all access to later-stage tables.
-- These narrow policies open only the completed platform paths; private records remain closed.
create policy posts_public_read on public.posts for select to anon,authenticated using(visibility='public' and status='published');
create policy posts_owner_read on public.posts for select to authenticated using(private.owns_post(id,auth.uid()));
create policy posts_owner_update on public.posts for update to authenticated using(private.owns_post(id,auth.uid())) with check(private.owns_post(id,auth.uid()));
create policy comments_public_read on public.comments for select to anon,authenticated using(exists(select 1 from public.posts p where p.id=post_id and p.visibility='public' and p.status='published'));
create policy comments_owner_write on public.comments for all to authenticated using(author_id=auth.uid()) with check(author_id=auth.uid());
create policy likes_self_write on public.likes for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy lessons_public_read on public.lessons for select to anon,authenticated using(is_published=true);
create policy library_public_read on public.library_items for select to anon,authenticated using(is_published=true);
create policy events_public_read on public.events for select to anon,authenticated using(is_published=true);
create policy registrations_self on public.event_registrations for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy notifications_self on public.notifications for select to authenticated using(user_id=auth.uid());
create policy notifications_update_self on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy conversations_member_read on public.conversations for select to authenticated using(exists(select 1 from public.conversation_members cm where cm.conversation_id=id and cm.user_id=auth.uid()));
create policy conversation_members_self_read on public.conversation_members for select to authenticated using(user_id=auth.uid());
create policy messages_member_read on public.messages for select to authenticated using(exists(select 1 from public.conversation_members cm where cm.conversation_id=messages.conversation_id and cm.user_id=auth.uid()));
create policy letters_participant_read on public.letters for select to authenticated using(sender_id=auth.uid() or (recipient_id=auth.uid() and status='sent' and (deliver_at is null or deliver_at<=now())));
create policy letters_sender_write on public.letters for all to authenticated using(sender_id=auth.uid()) with check(sender_id=auth.uid());
grant select on public.posts,public.comments,public.lessons,public.library_items,public.events to anon,authenticated;
grant select,update on public.notifications to authenticated;
grant select on public.conversations,public.conversation_members,public.messages,public.letters to authenticated;
grant select,insert,delete on public.event_registrations to authenticated;
drop policy if exists ahde_platform_media_select on storage.objects;
create policy ahde_platform_media_select on storage.objects for select to authenticated using(bucket_id='platform-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
drop policy if exists ahde_platform_media_insert on storage.objects;
create policy ahde_platform_media_insert on storage.objects for insert to authenticated with check(bucket_id='platform-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
drop policy if exists ahde_platform_media_update on storage.objects;
create policy ahde_platform_media_update on storage.objects for update to authenticated using(bucket_id='platform-media' and (storage.foldername(name))[1]=(select auth.uid())::text) with check(bucket_id='platform-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
drop policy if exists ahde_platform_media_delete on storage.objects;
create policy ahde_platform_media_delete on storage.objects for delete to authenticated using(bucket_id='platform-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
commit;
